// material to show Bayer dithering based on https://www.shadertoy.com/view/mtyGWy
void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;
    vec3 finalColor = vec3(0.0);

    for (float i = 0.0; i < 4.0; i++) {
        uv = fract(uv * 1.5) - 0.5;

        float d = length(uv) * exp(-length(uv0));

        vec3 col = palette(length(uv0) + i*.4 + iTime*.4);

        d = sin(d*8. + iTime)/8.;
        d = abs(d);

        d = pow(0.01 / d, 1.2);

        finalColor += col * d;
    }
    // INPUT 1 : leave milky background as is
    //finalColor = clamp(finalColor, 0.0, 1.0);

    // INPUT 2 : remove milky background
    finalColor = clamp(finalColor-0.2, 0.0, 1.0);


    vec3 linearColor = decodeSRGB(finalColor);

    // Bayer dithering (please load 8x8 grayscale bayer texture in iChannel0)
    float bayer = texture(iChannel0, fragCoord/8.0)[0];


    vec3 ditheredColor;

    // OPTION 1 : Using it badly on r,g,b separately in linear space
    vec3 tmp;
    tmp.r = (linearColor.r > bayer)?1.0:0.0;
    tmp.g = (linearColor.g > bayer)?1.0:0.0;
    tmp.b = (linearColor.b > bayer)?1.0:0.0;
    //ditheredColor = encodeSRGB(tmp);

    // OPTION 2 : Using it HSV (not less bad, just differently)
    vec3 hsvColor = rgb2hsv(linearColor);
    hsvColor[2] = (hsvColor[2] > bayer)?1.0:0.0;   
    ditheredColor = encodeSRGB(hsv2rgb(hsvColor));

    // NON OPTION 3 : Using it with perceptual luminance (very bad hue preservation)
    // Note that L* is in [0.0;100.0]    
    //vec3 labColor = rgb2lab(linearColor);
    //labColor[0] = (labColor[0] > bayer*100.0)?100.0:0.0;   
    //ditheredColor = encodeSRGB(lab2rgb(labColor));


    // Render with / without Bayer digthering
    if ( uv0.x > 0.005 ) { 
        fragColor = vec4(finalColor, 1.0);
    } else if ( uv0.x < -0.005 ) {
        fragColor = vec4(ditheredColor, 1.0);
    } else {
        if ( fract(uv0.y*20.0) < 0.5 ) {
            fragColor = vec4(1.0);
        } else {
            fragColor = vec4(0.0);
        }
    }
}

//https://iquilezles.org/articles/palettes/
vec3 palette( float t ) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263,0.416,0.557);

    return a + b*cos( 6.28318*(c*t+d) );
}

vec3 encodeSRGB(vec3 linearRGB)
{
    vec3 a = 12.92 * linearRGB;
    vec3 b = 1.055 * pow(linearRGB, vec3(1.0 / 2.4)) - 0.055;
    vec3 c = step(vec3(0.0031308), linearRGB);
    return mix(a, b, c);
}

vec3 decodeSRGB(vec3 screenRGB)
{
    vec3 a = screenRGB / 12.92;
    vec3 b = pow((screenRGB + 0.055) / 1.055, vec3(2.4));
    vec3 c = step(vec3(0.04045), screenRGB);
    return mix(a, b, c);
}

// All components are in the range [0…1], including hue.
vec3 rgb2hsv(vec3 c)
{
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}


// All components are in the range [0…1], including hue.
vec3 hsv2rgb(vec3 c)
{
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
